package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Explicit visible pitch matching; no automatic listening or sound output. */
public final class NoteChallengeActivity extends Activity {
 static final int CHALLENGE=798,FALLBACK=RESULT_FIRST_USER;String run,request;int unit,level;boolean preview;volatile boolean foreground;private boolean resumed,returned,attemptActive,done,math;private NoteAccess.Factory access;private NoteAccess.Operation operation;private TextView status,pitch;private final Handler main=new Handler(Looper.getMainLooper());private final Runnable changed=this::changed;private String issue="",shown="";
 static Intent preview(Activity activity,int level){return RecordUi.intent(activity,NoteChallengeActivity.class).putExtra("mode","preview").putExtra("level",level).putExtra("request",UUID.randomUUID().toString());}
 static Intent challenge(Activity activity,String run,int unit,String request,int level){return RecordUi.intent(activity,NoteChallengeActivity.class).putExtra("mode","challenge").putExtra("run",run).putExtra("unit",unit).putExtra("request",request).putExtra("level",level);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();String mode=getIntent().getStringExtra("mode");if(!Set.of("preview","challenge").contains(mode))throw new IllegalArgumentException();preview=mode.equals("preview");run=preview?request:getIntent().getStringExtra("run");unit=preview?0:getIntent().getIntExtra("unit",-1);level=getIntent().getIntExtra("level",-1);NotePitch.tolerance(level);if(run==null||run.isBlank()||run.length()>128||unit<0)throw new IllegalArgumentException();access=NoteAccess.factory;if(!access.current(this,run,unit))throw new IllegalArgumentException();if(saved!=null){done=saved.getBoolean("done");math=saved.getBoolean("math");}}catch(RuntimeException invalid){finish();return;}if(!preview){setShowWhenLocked(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}operation=access.existing(run,unit,level,changed);render();}
 boolean admission(){return foreground&&resumed&&hasWindowFocus()&&!isFinishing()&&!isDestroyed()&&access!=null&&access.current(this,run,unit);}
 private String signature(){return (operation==null?"IDLE":operation.state()+":"+operation.error())+":"+access.permission(this)+":"+issue+":"+done+":"+math;}
 private void changed(){if(isFinishing()||isDestroyed()||access==null)return;if(!shown.equals(signature()))render();else updateLive();}
 private String status(){NoteRuntime.State state=operation==null?NoteRuntime.State.IDLE:operation.state();return switch(state){case IDLE->"Ready when you are";case QUIETING->preview?"Preparing microphone…":"Waiting for alarm sound to stop…";case LISTENING->"Hold the target note · "+operation.accepted()+"%";case CLOSING->"Stopping microphone…";case BLOCKED->"Microphone cleanup needs attention";case DONE->attemptActive?"Target note matched":"Previous attempt ended. Listen again.";case ERROR,CANCELLED->operation.error().isEmpty()?"Listening stopped":operation.error();};}
 private void updateLive(){if(status!=null)status.setText(status());if(pitch!=null){double measured=operation==null?Double.NaN:operation.pitch();pitch.setText(Double.isFinite(measured)?String.format(Locale.getDefault(),"Heard %.1f Hz · %+.0f cents",measured,NotePitch.cents(measured,NotePitch.target(run,unit))):"Waiting for a clear sustained note");}}
 private void render(){if(isDestroyed()||isFinishing()||access==null)return;if(!access.current(this,run,unit)){finish();return;}if(operation!=null&&operation.state()==NoteRuntime.State.DONE&&operation.released()&&attemptActive&&admission()){attemptActive=false;if(preview)done=true;else{result(RESULT_OK);return;}}shown=signature();status=pitch=null;LinearLayout body=Design.page(this,false,null,null);RecordUi.label(this,body);RecordUi.header(body,preview?"Musical note preview":"Match a musical note",this::finish);Design.space(body,16);if(done){Design.text(body,math?"Math alternative completed":"Target note matched",25,600,Design.INK);Design.button(body,"Try again",true,()->{done=math=false;operation=null;render();});return;}if(math){WakePuzzleView.math(body,run,unit,level-1,this::admission,()->{done=true;render();});return;}Design.text(body,NotePitch.name(run,unit),48,600,Design.BROWN);Design.text(body,String.format(Locale.getDefault(),"Target %.1f Hz · ±%d cents",NotePitch.target(run,unit),NotePitch.tolerance(level)),15,500,Design.INK);Design.space(body,10);Design.text(body,"Hum or play this exact note and hold it steady for 1.2 seconds. This checks pitch, not words, instrument identity or who is performing. The app plays no reference tone.",14,400,Design.MUTED);Design.space(body,16);LinearLayout panel=Design.col(this);Design.pad(panel,18,20);panel.setBackground(Design.shape(this,Design.SOFT,18));status=Design.text(panel,status(),17,600,Design.BROWN);status.setContentDescription("Note listening status");status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);Design.space(panel,8);pitch=Design.text(panel,"",13,400,Design.MUTED);pitch.setContentDescription("Detected note frequency");body.addView(panel);updateLive();Design.space(body,18);NoteRuntime.State state=operation==null?NoteRuntime.State.IDLE:operation.state();NoteAccess.Permission permission=access.permission(this);boolean busy=operation!=null&&!operation.released();String unavailable=access.unavailable(this);if(!issue.isEmpty())Design.text(body,issue,13,500,NightDialTokens.NEGATIVE);else if(!busy&&!unavailable.isEmpty())Design.text(body,unavailable,13,500,Design.MUTED);if(permission!=NoteAccess.Permission.ALLOWED)Design.button(body,permission==NoteAccess.Permission.SETTINGS?"Open microphone settings":"Allow microphone",false,()->{try{access.request(this);}catch(RuntimeException failure){issue="Microphone settings could not open. Use Math.";render();}});if(state==NoteRuntime.State.BLOCKED)Design.button(body,"Retry microphone cleanup",true,()->operation.retry());else if(busy)Design.button(body,"Stop listening",false,()->operation.cancel());else{Button listen=Design.button(body,"Listen for target note",true,()->{if(!admission())return;issue="";attemptActive=true;try{operation=access.begin(this,run,unit,changed);}catch(RuntimeException failure){attemptActive=false;issue=failure.getMessage()==null?"Listening unavailable. Use Math.":failure.getMessage();}render();});RecordUi.enabled(listen,permission==NoteAccess.Permission.ALLOWED&&unavailable.isEmpty());}Design.space(body,10);Button fallback=Design.button(body,"Use Math instead",false,()->{if(!admission())return;if(operation!=null&&!operation.released()){operation.cancel();issue="Wait for microphone cleanup before switching.";render();return;}if(preview){math=true;render();}else result(FALLBACK);});RecordUi.enabled(fallback,!busy);Design.space(body,12);Design.text(body,preview?"Explicit listening only · no audio is saved or uploaded.":"Alarm sound pauses during this listening attempt. No audio is saved or uploaded.",12,400,Design.MUTED);}
 private void result(int result){if(returned||!admission())return;returned=true;setResult(result,new Intent().putExtra("run",run).putExtra("unit",unit).putExtra("request",request).putExtra("level",level).putExtra("captured",operation==null?-1:operation.captured()));finish();}
 private final Runnable poll=new Runnable(){public void run(){if(!resumed||access==null)return;if(!access.current(NoteChallengeActivity.this,run,unit)||!shown.equals(signature())||operation!=null&&attemptActive&&operation.state()==NoteRuntime.State.DONE)render();else updateLive();main.postDelayed(this,200);}};
 @Override protected void onResume(){super.onResume();resumed=true;foreground=hasWindowFocus();main.post(poll);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);foreground=resumed&&focus;if(focus){RecordUi.lightBars(this);if(access!=null)render();}else{attemptActive=false;if(operation!=null&&!operation.released())operation.cancel();}}
 @Override protected void onPause(){attemptActive=false;foreground=false;resumed=false;main.removeCallbacksAndMessages(null);if(operation!=null&&!operation.released())operation.cancel();super.onPause();}
 @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putBoolean("done",done);saved.putBoolean("math",math);}
 @Override protected void onDestroy(){foreground=false;main.removeCallbacksAndMessages(null);if(operation!=null&&!operation.released())operation.cancel();super.onDestroy();}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==NoteAccess.PERMISSION)render();}
}
